import{_ as t,c as e,o as r,a0 as n}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Mal for treningsdagbok","description":"","frontmatter":{},"headers":[],"relativePath":"no/diary-template.md","filePath":"no/diary-template.md"}');const i=t({name:"no/diary-template.md"},[["render",function(t,a,i,o,l,s){return r(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="mal-for-treningsdagbok" tabindex="-1">Mal for treningsdagbok <a class="header-anchor" href="#mal-for-treningsdagbok" aria-label="Permalink to &quot;Mal for treningsdagbok&quot;">​</a></h1><h2 id="slik-bruker-du-denne-malen" tabindex="-1">Slik bruker du denne malen <a class="header-anchor" href="#slik-bruker-du-denne-malen" aria-label="Permalink to &quot;Slik bruker du denne malen&quot;">​</a></h2><p>En treningsdagbok er din personlige oversikt over øvelse, fremgang og innsikt. Den hjelper deg med å spore hva som fungerer, identifisere mønstre og akselerere forbedring. Kopier avsnittene nedenfor til ditt foretrukne format (Word, Google Dokumenter, Excel, Google Regneark eller en notatbok).</p><div class="tip custom-block"><p class="custom-block-title">Kraften i refleksjon</p><p><strong>Det som måles, blir forbedret. Det som reflekteres over, blir mestret.</strong> En treningsdagbok forvandler tilfeldig øvelse til bevisst utvikling.</p></div><h2 id="mal-for-daglig-treningsoppføring" tabindex="-1">Mal for daglig treningsoppføring <a class="header-anchor" href="#mal-for-daglig-treningsoppføring" aria-label="Permalink to &quot;Mal for daglig treningsoppføring&quot;">​</a></h2><h3 id="kopier-denne-delen-for-hver-treningsøkt" tabindex="-1">Kopier denne delen for hver treningsøkt <a class="header-anchor" href="#kopier-denne-delen-for-hver-treningsøkt" aria-label="Permalink to &quot;Kopier denne delen for hver treningsøkt&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Time:</strong> ________ to ________ <strong>Duration:</strong> ________ minutes <strong>Location:</strong> ________ <strong>Terrain:</strong> Hard / Medium / Soft / Mixed <strong>Weather:</strong> Sunny / Cloudy / Windy / Rain</p><h3 id="training-partners" tabindex="-1">Training Partners <a class="header-anchor" href="#training-partners" aria-label="Permalink to &quot;Training Partners&quot;">​</a></h3><ul><li></li><li></li><li></li></ul><h3 id="today-s-intention" tabindex="-1">Today&#39;s Intention <a class="header-anchor" href="#today-s-intention" aria-label="Permalink to &quot;Today&#39;s Intention&quot;">​</a></h3><p>(What was my main focus for this session?)</p><hr><h3 id="teknisk-praksis" tabindex="-1">Teknisk praksis <a class="header-anchor" href="#teknisk-praksis" aria-label="Permalink to &quot;Teknisk praksis&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Øvd ferdighet</th><th>Repetisjoner/tid</th><th>Suksessrate</th><th>Notater</th></tr></thead><tbody><tr><td><strong>Peker</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Skyting</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Terrengavlesning</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Utvalg av bilder</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="hva-fungerte-bra" tabindex="-1">Hva fungerte bra? <a class="header-anchor" href="#hva-fungerte-bra" aria-label="Permalink to &quot;Hva fungerte bra?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="hva-trenger-forbedring" tabindex="-1">Hva trenger forbedring? <a class="header-anchor" href="#hva-trenger-forbedring" aria-label="Permalink to &quot;Hva trenger forbedring?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="viktig-innsikt" tabindex="-1">Viktig innsikt <a class="header-anchor" href="#viktig-innsikt" aria-label="Permalink to &quot;Viktig innsikt&quot;">​</a></h3><p>(En viktig lærdom fra i dag)</p><hr><h3 id="mental-game" tabindex="-1">Mental Game <a class="header-anchor" href="#mental-game" aria-label="Permalink to &quot;Mental Game&quot;">​</a></h3><p><strong>Energy Level (1-10):</strong> _____ <strong>Focus Quality (1-10):</strong> _____ <strong>Confidence (1-10):</strong> _____</p><p><strong>Mental Challenges Today:</strong></p><p><strong>How I Handled Them:</strong></p><p><strong>Mental Technique Practiced:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Other: ________</li></ul><hr><h3 id="fysisk-tilstand" tabindex="-1">Fysisk tilstand <a class="header-anchor" href="#fysisk-tilstand" aria-label="Permalink to &quot;Fysisk tilstand&quot;">​</a></h3><p><strong>Kroppsfølelse (1–10):</strong> _____ <strong>Smerte/ubehag:</strong> _____ <strong>Tretthetsnivå (1–10):</strong> _____</p><p><strong>Fysiske merknader:</strong></p><hr><h3 id="tomorrow-s-focus" tabindex="-1">Tomorrow&#39;s Focus <a class="header-anchor" href="#tomorrow-s-focus" aria-label="Permalink to &quot;Tomorrow&#39;s Focus&quot;">​</a></h3><p>(Based on today, what will I work on next session?)</p><hr><h2 id="mal-for-konkurranse-kamppamelding" tabindex="-1">Mal for konkurranse-/kamppåmelding <a class="header-anchor" href="#mal-for-konkurranse-kamppamelding" aria-label="Permalink to &quot;Mal for konkurranse-/kamppåmelding&quot;">​</a></h2><h3 id="kopier-denne-delen-for-hver-konkurranse" tabindex="-1">Kopier denne delen for hver konkurranse <a class="header-anchor" href="#kopier-denne-delen-for-hver-konkurranse" aria-label="Permalink to &quot;Kopier denne delen for hver konkurranse&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Tournament:</strong> ________ <strong>Format:</strong> Triples / Doubles / Singles <strong>Team:</strong> ________</p><h3 id="pre-competition" tabindex="-1">Pre-Competition <a class="header-anchor" href="#pre-competition" aria-label="Permalink to &quot;Pre-Competition&quot;">​</a></h3><p><strong>Sleep Quality (1-10):</strong> _____ <strong>Nutrition:</strong> _____ <strong>Mental State (1-10):</strong> _____ <strong>Physical Warm-up:</strong> Yes / No <strong>Mental Warm-up:</strong> Yes / No</p><hr><h3 id="kampresultater" tabindex="-1">Kampresultater <a class="header-anchor" href="#kampresultater" aria-label="Permalink to &quot;Kampresultater&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Runde</th><th>Motstander</th><th>Poengsum</th><th>Resultat</th><th>Viktige øyeblikk</th></tr></thead><tbody><tr><td><strong>1</strong></td><td></td><td></td><td>H / L</td><td></td></tr><tr><td><strong>2</strong></td><td></td><td></td><td>H / L</td><td></td></tr><tr><td><strong>3</strong></td><td></td><td></td><td>H / L</td><td></td></tr><tr><td><strong>4</strong></td><td></td><td></td><td>H / L</td><td></td></tr></tbody></table><p><strong>Endelig plassering:</strong> _____</p><hr><h3 id="performance-analysis" tabindex="-1">Performance Analysis <a class="header-anchor" href="#performance-analysis" aria-label="Permalink to &quot;Performance Analysis&quot;">​</a></h3><p><strong>Technical Performance (1-10):</strong> _____ <strong>Mental Performance (1-10):</strong> _____ <strong>Tactical Decisions (1-10):</strong> _____ <strong>Team Communication (1-10):</strong> _____</p><h3 id="what-i-did-well" tabindex="-1">What I Did Well <a class="header-anchor" href="#what-i-did-well" aria-label="Permalink to &quot;What I Did Well&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="what-cost-me-points" tabindex="-1">What Cost Me Points <a class="header-anchor" href="#what-cost-me-points" aria-label="Permalink to &quot;What Cost Me Points&quot;">​</a></h3><ol><li></li><li></li></ol><h2 id="monthly-summary-template" tabindex="-1">Monthly Summary Template <a class="header-anchor" href="#monthly-summary-template" aria-label="Permalink to &quot;Monthly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Måned:</strong> ________ <strong>År:</strong> ________</p><h3 id="manedlig-statistikk" tabindex="-1">Månedlig statistikk <a class="header-anchor" href="#manedlig-statistikk" aria-label="Permalink to &quot;Månedlig statistikk&quot;">​</a></h3><p><strong>Totalt antall treningstimer:</strong> _____ <strong>Totalt antall økter:</strong> _____ <strong>Påmeldte konkurranser:</strong> _____ <strong>Seiersrate:</strong> _____%</p><h3 id="teknisk-fremgang" tabindex="-1">Teknisk fremgang <a class="header-anchor" href="#teknisk-fremgang" aria-label="Permalink to &quot;Teknisk fremgang&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ferdighet</th><th>Månedens start</th><th>Månedens slutt</th><th>Forbedring</th></tr></thead><tbody><tr><td><strong>Pekepresisjon</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Konsistens i skyting</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Terrengtilpasning</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Utvalg av bilder</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="mental-spillfremgang" tabindex="-1">Mental spillfremgang <a class="header-anchor" href="#mental-spillfremgang" aria-label="Permalink to &quot;Mental spillfremgang&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Område</th><th>Starten av måneden</th><th>Slutten av måneden</th><th>Forbedring</th></tr></thead><tbody><tr><td><strong>Trykkhåndtering</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Fokuskvalitet</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Selvtillit</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Bruk av indre trener</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="manedlige-høydepunkter" tabindex="-1">Månedlige høydepunkter <a class="header-anchor" href="#manedlige-høydepunkter" aria-label="Permalink to &quot;Månedlige høydepunkter&quot;">​</a></h3><p><strong>Beste treningsøkt:</strong></p><p><strong>Beste konkurranseprestasjon:</strong></p><p><strong>Største gjennombrudd:</strong></p><p><strong>Mest verdifull læring:</strong></p><h3 id="utfordringer-overvunnet" tabindex="-1">Utfordringer overvunnet <a class="header-anchor" href="#utfordringer-overvunnet" aria-label="Permalink to &quot;Utfordringer overvunnet&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="løpende-utfordringer" tabindex="-1">Løpende utfordringer <a class="header-anchor" href="#løpende-utfordringer" aria-label="Permalink to &quot;Løpende utfordringer&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="neste-maneds-prioriteringer" tabindex="-1">Neste måneds prioriteringer <a class="header-anchor" href="#neste-maneds-prioriteringer" aria-label="Permalink to &quot;Neste måneds prioriteringer&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr><h2 id="specific-practice-tracking-templates" tabindex="-1">Specific Practice Tracking Templates <a class="header-anchor" href="#specific-practice-tracking-templates" aria-label="Permalink to &quot;Specific Practice Tracking Templates&quot;">​</a></h2><h3 id="pointing-practice-log" tabindex="-1">Pointing Practice Log <a class="header-anchor" href="#pointing-practice-log" aria-label="Permalink to &quot;Pointing Practice Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Distance</th><th>Terrain</th><th>Attempts</th><th>Within 10cm</th><th>Within 20cm</th><th>Within 50cm</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions:</strong></p><ul><li>Track pointing accuracy at different distances (6m, 7m, 8m, 9m, 10m)</li><li>Record terrain type (hard, medium, soft)</li><li>Count successes in each distance range</li><li>Calculate success rate over time</li></ul><hr><h3 id="logg-for-skyteøvelser" tabindex="-1">Logg for skyteøvelser <a class="header-anchor" href="#logg-for-skyteøvelser" aria-label="Permalink to &quot;Logg for skyteøvelser&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dato</th><th>Måltype</th><th>Avstand</th><th>Forsøk</th><th>Direkte treff</th><th>Karusell</th><th>Forskyvning</th><th>Merknader</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Måltyper:</strong></p><ul><li>Statisk ball</li><li>Ball mot spikeren</li><li>Ball i klyngen</li><li>Bevegelig mål (avansert)</li></ul><hr><h3 id="mental-training-log" tabindex="-1">Mental Training Log <a class="header-anchor" href="#mental-training-log" aria-label="Permalink to &quot;Mental Training Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Technique Practiced</th><th>Duration</th><th>Situation</th><th>Effectiveness (1-10)</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Techniques:</strong></p><ul><li>3-Breath Reset</li><li>Inner Coach Reframe</li><li>Visualization</li><li>Mindfulness Practice</li><li>Pre-shot Routine</li><li>Pressure Simulation</li></ul><hr><h2 id="hurtig-daglig-registrering-forenklet" tabindex="-1">Hurtig daglig registrering (forenklet) <a class="header-anchor" href="#hurtig-daglig-registrering-forenklet" aria-label="Permalink to &quot;Hurtig daglig registrering (forenklet)&quot;">​</a></h2><h3 id="for-travle-dager-–-kopier-denne-minimalistiske-malen" tabindex="-1">For travle dager – Kopier denne minimalistiske malen <a class="header-anchor" href="#for-travle-dager-–-kopier-denne-minimalistiske-malen" aria-label="Permalink to &quot;For travle dager – Kopier denne minimalistiske malen&quot;">​</a></h3><hr><p><strong>Date:</strong> ________</p><p><strong>Trained:</strong> Yes / No <strong>Duration:</strong> _____ min <strong>Focus:</strong> ________ <strong>Energy (1-10):</strong> _____ <strong>Quality (1-10):</strong> _____</p><p><strong>One Win:</strong></p><p><strong>One Learning:</strong></p><p><strong>Tomorrow&#39;s Focus:</strong></p><hr><h2 id="refleksjonsoppgaver" tabindex="-1">Refleksjonsoppgaver <a class="header-anchor" href="#refleksjonsoppgaver" aria-label="Permalink to &quot;Refleksjonsoppgaver&quot;">​</a></h2><p>Bruk disse tipsene for å utdype dagboknotatene dine:</p><h3 id="etter-trening" tabindex="-1">Etter trening <a class="header-anchor" href="#etter-trening" aria-label="Permalink to &quot;Etter trening&quot;">​</a></h3><ol><li>Hva overrasket meg i dag?</li><li>Når følte jeg meg mest selvsikker?</li><li>Når slet jeg? Hvorfor?</li><li>Hva ville jeg gjort annerledes?</li><li>Hva er jeg takknemlig for fra denne økten?</li></ol><h3 id="etter-konkurransen" tabindex="-1">Etter konkurransen <a class="header-anchor" href="#etter-konkurransen" aria-label="Permalink to &quot;Etter konkurransen&quot;">​</a></h3><ol><li>Hva lærte jeg om meg selv i dag?</li><li>Hvordan håndterte jeg presset?</li><li>Hva ville min indre coach si om prestasjonen min?</li><li>Hva vil jeg øve annerledes på basert på i dag?</li><li>Hva er jeg stolt av, uavhengig av resultatet?</li></ol><h3 id="ukentlig-refleksjon" tabindex="-1">Ukentlig refleksjon <a class="header-anchor" href="#ukentlig-refleksjon" aria-label="Permalink to &quot;Ukentlig refleksjon&quot;">​</a></h3><ol><li>Hvilket mønster legger jeg merke til i praksisen min?</li><li>Trener jeg på det jeg sliter med i konkurranser?</li><li>Blir mitt mentale spill bedre?</li><li>Koser jeg meg med prosessen?</li><li>Hva må endres neste uke?</li></ol><h3 id="manedlig-refleksjon" tabindex="-1">Månedlig refleksjon <a class="header-anchor" href="#manedlig-refleksjon" aria-label="Permalink to &quot;Månedlig refleksjon&quot;">​</a></h3><ol><li>Er jeg nærmere målene mine enn forrige måned?</li><li>Hva fungerer i treningsmetoden min?</li><li>Hva fungerer ikke?</li><li>Må jeg justere målene mine?</li><li>Hva vil jeg huske fra denne måneden?</li></ol><hr><h2 id="tips-for-effective-diary-keeping" tabindex="-1">Tips for Effective Diary Keeping <a class="header-anchor" href="#tips-for-effective-diary-keeping" aria-label="Permalink to &quot;Tips for Effective Diary Keeping&quot;">​</a></h2><h3 id="_1-write-immediately-after-training" tabindex="-1">1. Write Immediately After Training <a class="header-anchor" href="#_1-write-immediately-after-training" aria-label="Permalink to &quot;1. Write Immediately After Training&quot;">​</a></h3><p><strong>Why:</strong> Details are fresh, emotions are real, insights are clear</p><p><strong>How:</strong> Keep diary in your bag, set 10 minutes aside after each session</p><h3 id="_2-be-honest-not-perfect" tabindex="-1">2. Be Honest, Not Perfect <a class="header-anchor" href="#_2-be-honest-not-perfect" aria-label="Permalink to &quot;2. Be Honest, Not Perfect&quot;">​</a></h3><p><strong>Don&#39;t:</strong> Write what you think you should write <strong>Do:</strong> Write what actually happened and how you really felt</p><h3 id="_3-focus-on-process-not-just-results" tabindex="-1">3. Focus on Process, Not Just Results <a class="header-anchor" href="#_3-focus-on-process-not-just-results" aria-label="Permalink to &quot;3. Focus on Process, Not Just Results&quot;">​</a></h3><p><strong>Don&#39;t:</strong> &quot;Missed 7 out of 10 shots - terrible&quot; <strong>Do:</strong> &quot;Missed 7 out of 10 shots - noticed I was rushing my routine, will slow down next time&quot;</p><h3 id="_4-look-for-patterns" tabindex="-1">4. Look for Patterns <a class="header-anchor" href="#_4-look-for-patterns" aria-label="Permalink to &quot;4. Look for Patterns&quot;">​</a></h3><p>Review your diary weekly to spot:</p><ul><li>Recurring technical issues</li><li>Mental game patterns</li><li>Energy/performance correlations</li><li>What conditions you perform best in</li></ul><h3 id="_5-celebrate-progress" tabindex="-1">5. Celebrate Progress <a class="header-anchor" href="#_5-celebrate-progress" aria-label="Permalink to &quot;5. Celebrate Progress&quot;">​</a></h3><p><strong>Every month:</strong> Read entries from 3 months ago <strong>Notice:</strong> How much you&#39;ve improved <strong>Acknowledge:</strong> The work you&#39;ve put in</p><hr><h2 id="digital-vs-papirdagbok" tabindex="-1">Digital vs. papirdagbok <a class="header-anchor" href="#digital-vs-papirdagbok" aria-label="Permalink to &quot;Digital vs. papirdagbok&quot;">​</a></h2><h3 id="digitalt-google-dokumenter-regneark-notion-apper" tabindex="-1">Digitalt (Google Dokumenter/Regneark, Notion, Apper) <a class="header-anchor" href="#digitalt-google-dokumenter-regneark-notion-apper" aria-label="Permalink to &quot;Digitalt (Google Dokumenter/Regneark, Notion, Apper)&quot;">​</a></h3><p><strong>Fordeler:</strong></p><ul><li>Enkelt å søke i tidligere oppføringer</li><li>Kan legge til bilder/videoer</li><li>Automatiske datostempler</li><li>Kan dele med trener</li><li>Alltid tilgjengelig på telefon</li></ul><p><strong>Ulemper:</strong></p><ul><li>Skjermtid</li><li>Kan føles upersonlig</li><li>Distraksjoner fra varsler</li></ul><p><strong>Best for:</strong> Detaljert statistikksporing, langsiktig mønsteranalyse</p><h3 id="papir-notatbok-trykte-maler" tabindex="-1">Papir (notatbok, trykte maler) <a class="header-anchor" href="#papir-notatbok-trykte-maler" aria-label="Permalink to &quot;Papir (notatbok, trykte maler)&quot;">​</a></h3><p><strong>Fordeler:</strong></p><ul><li>Taktil, personlig kontakt</li><li>Ingen distraksjoner</li><li>Lett å skissere diagrammer</li><li>Tilfredsstillende ritual</li><li>Bedre for refleksjon</li></ul><p><strong>Ulemper:</strong></p><ul><li>Kan miste notatboken</li><li>Vanskelig å søke etter gamle oppføringer</li><li>Kan ikke dele lett</li></ul><p><strong>Best for:</strong> Daglige refleksjoner, notater rett etter trening</p><p><strong>Anbefaling:</strong> Hybrid tilnærming – papir for daglige oppføringer, digitalt for månedlige sammendrag og statistikk</p><hr><h2 id="sample-entries" tabindex="-1">Sample Entries <a class="header-anchor" href="#sample-entries" aria-label="Permalink to &quot;Sample Entries&quot;">​</a></h2><h3 id="example-good-training-entry" tabindex="-1">Example: Good Training Entry <a class="header-anchor" href="#example-good-training-entry" aria-label="Permalink to &quot;Example: Good Training Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 15, 2024 <strong>Duration:</strong> 90 minutes <strong>Location:</strong> Club terrain <strong>Terrain:</strong> Hard <strong>Weather:</strong> Sunny, light wind</p><p><strong>Today&#39;s Intention:</strong> Improve pointing accuracy at 8m</p><p><strong>Technical Practice:</strong></p><ul><li>Pointing at 8m: 30 attempts, 18 within 20cm (60%)</li><li>Noticed I&#39;m more accurate when I take 3 breaths before throwing</li><li>Struggled when wind picked up - need to adjust for wind better</li></ul><p><strong>What Worked Well:</strong></p><ol><li>Pre-shot routine was consistent</li><li>Stayed calm after misses</li><li>Adjusted grip for hard terrain</li></ol><p><strong>Key Insight:</strong> My accuracy drops when I rush. Slowing down by 2 seconds improves success rate significantly.</p><p><strong>Mental Game:</strong></p><ul><li>Energy: 8/10</li><li>Focus: 7/10</li><li>Used Inner Coach after 3 bad throws - helped me reset</li></ul><p><strong>Tomorrow&#39;s Focus:</strong> Practice pointing in windy conditions, maintain slow routine</p></details><h3 id="example-good-competition-entry" tabindex="-1">Example: Good Competition Entry <a class="header-anchor" href="#example-good-competition-entry" aria-label="Permalink to &quot;Example: Good Competition Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 20, 2024 <strong>Tournament:</strong> Regional Championship <strong>Format:</strong> Triples <strong>Final Placement:</strong> 5th of 16 teams</p><p><strong>Performance Analysis:</strong></p><ul><li>Technical: 7/10 - Pointing was solid, shooting was inconsistent</li><li>Mental: 8/10 - Stayed calm under pressure</li><li>Tactical: 6/10 - Made one bad decision in semi-final</li></ul><p><strong>Best Moment:</strong> Carreau in quarter-final to win 13-12</p><p><strong>Toughest Moment:</strong> Semi-final, 11-11, rushed a shot and missed badly</p><p><strong>Key Learning:</strong> When score is tight, I need to slow down even more, not speed up. My Inner Critic tried to take over (&quot;Don&#39;t mess this up!&quot;) but I caught it and used Inner Coach instead (&quot;You&#39;ve made this shot 100 times, trust your routine&quot;).</p><p><strong>For Next Competition:</strong> Practice pressure situations in training - simulate 11-11 scenarios</p></details><hr><h2 id="relaterte-ressurser" tabindex="-1">Relaterte ressurser <a class="header-anchor" href="#relaterte-ressurser" aria-label="Permalink to &quot;Relaterte ressurser&quot;">​</a></h2><ul><li><a href="/no/målmal">Mal for målsetting</a> - Sett og følg opp forbedringsmålene dine</li><li><a href="/no/workshop">Workshop</a> - Gruppesamlinger om mentalt spill og refleksjon</li><li><a href="/no/opplæringsøkt">Opplæringsøkt</a> - Strukturert øving med jevnaldrende</li><li><a href="/no/utdanning/mental-styrke">Mental styrke</a> - Bygg mental motstandskraft</li><li><a href="/no/utdanning/mindfulness">Mindfulness</a> - Utvikle bevissthet og fokus</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to diary keeping? Start here:</strong></p><p><strong>Week 1:</strong> Use Quick Daily Entry (5 minutes after each session) <strong>Week 2:</strong> Add one reflection prompt per entry <strong>Week 3:</strong> Try full Daily Training Entry <strong>Week 4:</strong> Do first Weekly Summary</p><p><strong>After one month:</strong> Add Monthly Summary and specific practice logs</p><hr><div class="warning custom-block"><p class="custom-block-title">Vanlige dagbokfeil</p><ol><li><strong>For detaljert</strong> - Bruker 30 minutter på å skrive, og slutter deretter etter en uke</li><li><strong>For vag</strong> – «Trent i dag, gikk greit» hjelper deg ikke med å forbedre deg</li><li><strong>Kun registrering av feil</strong> – Feir seire også!</li><li><strong>Aldri gjennomgang</strong> – Styrken ligger i å lese tidligere innlegg</li><li><strong>For lenge ventende</strong> - Skriv innen 30 minutter etter at du er ferdig</li></ol></div><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Evernote</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Daily Training Entry Template</li><li>Competition/Match Entry Template</li><li>Weekly Summary Template</li></ol><hr><p><strong>Beste øyeblikk:</strong></p><p><strong>Vanskeligste øyeblikk:</strong></p><p><strong>Slik svarte jeg:</strong></p><hr><h3 id="mental-game-in-competition" tabindex="-1">Mental Game in Competition <a class="header-anchor" href="#mental-game-in-competition" aria-label="Permalink to &quot;Mental Game in Competition&quot;">​</a></h3><p><strong>Pressure Situations:</strong></p><p><strong>How I Managed Pressure:</strong></p><p><strong>Inner Critic Activity (1-10):</strong> _____ <strong>Inner Coach Activity (1-10):</strong> _____</p><p><strong>Mental Techniques Used:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Routine Consistency</li><li>[ ] Other: ________</li></ul><hr><h3 id="viktige-lærdommer" tabindex="-1">Viktige lærdommer <a class="header-anchor" href="#viktige-lærdommer" aria-label="Permalink to &quot;Viktige lærdommer&quot;">​</a></h3><p><strong>Teknisk:</strong></p><p><strong>Taktisk:</strong></p><p><strong>Mental:</strong></p><p><strong>For neste konkurranse:</strong></p><hr><h2 id="weekly-summary-template" tabindex="-1">Weekly Summary Template <a class="header-anchor" href="#weekly-summary-template" aria-label="Permalink to &quot;Weekly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Uke med:</strong> ________</p><h3 id="treningsoversikt" tabindex="-1">Treningsoversikt <a class="header-anchor" href="#treningsoversikt" aria-label="Permalink to &quot;Treningsoversikt&quot;">​</a></h3><p><strong>Totalt antall treningstimer:</strong> _____ <strong>Antall økter:</strong> _____ <strong>Konkurransetider:</strong> _____ <strong>Mental trening:</strong> _____ minutter <strong>Fysisk trening:</strong> _____ økter</p><h3 id="ukentlig-fremgang" tabindex="-1">Ukentlig fremgang <a class="header-anchor" href="#ukentlig-fremgang" aria-label="Permalink to &quot;Ukentlig fremgang&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Målområde</th><th>Delmål</th><th>Faktisk</th><th>Fremgang</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="denne-ukens-seire" tabindex="-1">Denne ukens seire <a class="header-anchor" href="#denne-ukens-seire" aria-label="Permalink to &quot;Denne ukens seire&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="denne-ukens-utfordringer" tabindex="-1">Denne ukens utfordringer <a class="header-anchor" href="#denne-ukens-utfordringer" aria-label="Permalink to &quot;Denne ukens utfordringer&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="mønstergjenkjenning" tabindex="-1">Mønstergjenkjenning <a class="header-anchor" href="#mønstergjenkjenning" aria-label="Permalink to &quot;Mønstergjenkjenning&quot;">​</a></h3><p>(Hvilke mønstre legger jeg merke til i min praksis/fremførelse?)</p><h3 id="fokus-neste-uke" tabindex="-1">Fokus neste uke <a class="header-anchor" href="#fokus-neste-uke" aria-label="Permalink to &quot;Fokus neste uke&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr>',195)])])}]]);export{a as __pageData,i as default};
